import json
from pathlib import Path

import requests

MANIFEST_PATH = Path(__file__).resolve().parent.parent / "diagnostics.json"
TIMEOUT_SECONDS = 5.0


def _manifest_urls() -> list[str]:
    """Load the maintainer-authored allowlist of diagnostic URLs."""
    return json.loads(MANIFEST_PATH.read_text(encoding="utf-8"))


def fetch(url: str) -> str:
    """Return the complete UTF-8 diagnostic text for a manifest-listed URL.

    Only URLs listed in the local diagnostics.json manifest are accepted;
    anything else is rejected. Redirects between the manifest's local
    services are followed normally.
    """
    if url not in _manifest_urls():
        raise ValueError(f"URL not in diagnostic manifest: {url!r}")
    response = requests.get(url, timeout=TIMEOUT_SECONDS, allow_redirects=True)
    response.raise_for_status()
    return response.content.decode("utf-8")
